const campanas = $input.all().flatMap(i => i.json.data || []);
const fecha = new Date();
fecha.setDate(fecha.getDate() - 1);
const fechaStr = fecha.toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' });

let totalGasto = 0, totalCompras = 0;
const filas = campanas.map(c => {
  const ins = c.insights?.data?.[0];
  const gasto = parseFloat(ins?.spend || 0);
  const compras = ins?.actions?.find(a => a.action_type === 'purchase')?.value || 0;
  const roas = parseFloat(ins?.purchase_roas?.[0]?.value || 0);
  const cpc = parseFloat(ins?.cpc || 0);
  const cpm = parseFloat(ins?.cpm || 0);
  totalGasto += gasto;
  totalCompras += parseInt(compras);
  const roasColor = roas >= 2 ? '#108043' : roas >= 1.2 ? '#E65100' : '#C62828';
  const statusIcon = c.status === 'ACTIVE' ? '🟢' : '⏸️';
  return `<tr>
    <td style='padding:6px 10px;font-size:13px'>${statusIcon} ${c.name.slice(0, 40)}</td>
    <td style='padding:6px 10px;text-align:center'>$${gasto.toFixed(0)}</td>
    <td style='padding:6px 10px;text-align:center'>${compras}</td>
    <td style='padding:6px 10px;text-align:center;color:${roasColor};font-weight:700'>${roas > 0 ? roas.toFixed(2) + 'x' : '—'}</td>
    <td style='padding:6px 10px;text-align:center'>$${cpc.toFixed(2)}</td>
    <td style='padding:6px 10px;text-align:center'>$${cpm.toFixed(1)}</td>
  </tr>`;
}).join('');
return [{ json: { fechaStr, filas, totalGasto: totalGasto.toFixed(2), totalCompras } }];
